WITH latest_match AS (SELECT s.id, s.store_id, s.status, s.amount, s.shipping_fee, x.delivered_date FROM orders s LEFT JOIN LATERAL (SELECT c.delivered_date FROM shipments c WHERE c.order_id = s.id ORDER BY c.cost DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT s.id, s.store_id, s.status, s.shipping_fee, (SELECT SUM(t2.amount) FROM orders t2 WHERE t2.store_id = s.store_id) AS sum_order_amount FROM latest_match s ORDER BY sum_order_amount
